to;font-size:11px;color:#7aa542}.mission-tip{border-top:1px solid #e7e9e2;margin-top:auto;padding-top:12px;display:flex;gap:9px;align-items:flex-start}.tip-icon{font-size:15px;color:#98bd62}.mission-tip p{font-size:9px;color:#818a83;line-height:1.55;margin:1px 0 0}.sim-panel{padding:19px 20px 14px;display:flex;flex-direction:column}.sim-topline{display:flex;justify-content:space-between;align-items:flex-start}.sim-coordinate{font-size:8px;color:#a1aaa2;letter-spacing:.03em}.room-title{font:500 13px var(--mono);letter-spacing:.035em;margin-top:8px}.room-title span{color:#a1aaa2}.sim-actions{display:flex;gap:5px}.icon-btn{background:transparent;border:1px solid #dfe3da;padding:7px 8px;color:#65716a;font-size:11px;cursor:pointer}.icon-btn:hover{background:#f1f3ec}.icon-btn span{font-size:8px;margin-left:3px}.canvas-wrap{position:relative;background:#182124;margin-top:15px;flex:1;min-height:290px;overflow:hidden;border:1px solid #273538}.canvas-wrap canvas{display:block;width:100%;height:100%;min-height:290px}.canvas-overlay{pointer-events:none;position:absolute;left:13px;bottom:11px;background:#121a1ddc;border:1px solid #ffffff12;color:#b1beb1;font:8px var(--mono);letter-spacing:.1em;padding:7px 8px;display:flex;align-items:center;gap:7px;transition:opacity .2s}.canvas-overlay.hidden{opacity:0}.overlay-icon{color:var(--green);font-size:12px}.canvas-corner{position:absolute;width:13px;height:13px;pointer-events:none}.corner-tl{top:7px;left:7px;border-top:1px solid #b7f35c88;border-left:1px solid #b7f35c88}.corner-br{right:7px;bottom:7px;border-right:1px solid #b7f35c88;border-bottom:1px solid #b7f35c88}.world-legend{display:flex;align-items:center;gap:17px;padding-top:13px;color:#89928b;font-size:8px}.world-legend i{font-style:normal}.legend-robot{color:var(--green);font-size:12px}.legend-cell{display:inline-block;width:6px;height:6px;background:#ffb855;transform:rotate(45deg);margin-right:4px}.legend-exit{color:#e8f4dc;font-size:12px}.legend-right{margin-left:auto;colo